import{_ as a,o as t,c as h,a1 as i}from"./chunks/framework.DK3UFCr3.js";const m="/40years/bapchay.jpg",s=JSON.parse('{"title":"Cảm ơn người nhóm lửa","description":"","frontmatter":{"layout":"doc","title":"Cảm ơn người nhóm lửa","author":"Nguyen Van Tam"},"headers":[],"relativePath":"nvt.md","filePath":"nvt.md"}'),g={name:"nvt.md"};function c(r,n,l,o,e,u){return t(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="cam-on-nguoi-nhom-lua" tabindex="-1">Cảm ơn người nhóm lửa <a class="header-anchor" href="#cam-on-nguoi-nhom-lua" aria-label="Permalink to &quot;Cảm ơn người nhóm lửa&quot;">​</a></h1><p>Hi @all C3,</p><p>Lời đầu tiên tui muốn viết là xin cám ơn các bạn đã hiểu và cảm thông cho tui vì cuộc hội ngộ 40 năm, tui là người đến trễ và về sớm. Bởi vậy phút dạo đầu và kết thúc không hiện diện (hơi uổng). Chỉ trọn vẹn về đêm đầy cảm xúc khó quên nhứt là “nhóm lửa trại”.</p><p>Trong đêm họp lớp kỷ niệm 40 năm ngày ra trường, tui cảm nhận: Giữa tiếng sóng biển rì rào, làn gió mơn man mang theo vị mặn của biển, thổi qua những mái tóc, gương mặt đã nhuốm màu thời gian, người nhóm lửa lặng lẽ cúi mình châm lên ngọn lửa đầu tiên. Từ vài tia lửa nhỏ, ngọn lửa bùng lên sáng rực, soi rõ những ánh mắt xúc động của bạn bè sau 40 năm xa cách. Người nhóm lửa hôm nay không chỉ đốt cháy những thanh củi, nướng đen khoai lang, trái bắp mà còn khơi lại bao kí ức của một thời áo trắng: những buổi đến lớp, những nghịch ngợm tuổi học trò, những ước mơ từng cùng nhau chia sẻ. Ngọn lửa ấy như sợi dây nối quá khứ với hiện tại, để rồi mỗi chúng ta nhận ra rằng dù thời gian có đổi thay, dù địa lý cách trở, tình bạn vẫn cháy âm ỉ trong tim như than hồng không bao giờ tắt. Và trong khoảnh khắc các bạn nắm tay nhau quanh đống lửa cùng hát Nối Vòng Tay Lớn - Nổi Lửa Lên Em thật ấm áp, thật xúc động, ai cũng hiểu rằng người nhóm lửa chính là người đã thắp lại hơi ấm tình bạn C3 sau 40 năm ra trường.</p><p><img src="'+m+'" alt="bap chay"> (Đêm đó tui không ngủ)</p><p>Hẹn gặp kỉ niệm 42 năm.</p><p>Cám ơn người nhóm lửa.</p><h3 id="nguyen-van-tam" tabindex="-1">Nguyễn Văn Tâm <a class="header-anchor" href="#nguyen-van-tam" aria-label="Permalink to &quot;Nguyễn Văn Tâm&quot;">​</a></h3><p>23/07/2026</p>',9)])])}const d=a(g,[["render",c]]);export{s as __pageData,d as default};
